-- @@name@@: Hyprland rice (void-postinstall)
-- Generated by void-rice from palettes/@@rice@@.conf. Change colours/fonts/gaps
-- there (or in ~/.config/void-rice/@@rice@@.conf) and run `void-rice apply @@rice@@`.
-- Hyprland >= 0.55 reads this Lua file in preference to hyprland.conf
-- (0.56.1 deprecated the .conf format).

local mod = "SUPER"

------------------------------------------------------------------ monitors
hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })

------------------------------------------------------------------ environment
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

------------------------------------------------------------------ autostart
-- `rice autostart` brings up waybar, mako, swaybg, hypridle, the polkit
-- agent and the tray applets, and exports WAYLAND_DISPLAY to D-Bus so
-- portals (screen sharing, file pickers) work. PipeWire was already started
-- by void-session: do NOT start pipewire/wireplumber here.
hl.on("hyprland.start", function()
    hl.exec_cmd("rice autostart")
end)

------------------------------------------------------------------ look
hl.config({
    general = {
        gaps_in = @@gaps_in@@,
        gaps_out = @@gaps_out@@,
        border_size = @@border@@,
        col = {
            active_border = { colors = { "rgba(@@accent_hex@@ff)", "rgba(@@accent2_hex@@ff)" }, angle = 45 },
            inactive_border = "rgba(@@bg_hi_hex@@cc)",
        },
        resize_on_border = true,
        allow_tearing = false,
        layout = "dwindle",
    },

    decoration = {
        rounding = @@radius@@,
        rounding_power = 2,
        active_opacity = 1.0,
        inactive_opacity = 0.95,
        dim_inactive = false,
        shadow = {
            enabled = true,
            range = 20,
            render_power = 3,
            color = 0xcc0a0705,
        },
        blur = {
            enabled = true,
            size = 6,
            passes = 2,
            vibrancy = 0.17,
            popups = true,
        },
    },

    animations = { enabled = true },

    dwindle = { preserve_split = true },
    master = { new_status = "master" },

    misc = {
        force_default_wallpaper = 0,
        disable_hyprland_logo = true,
        disable_splash_rendering = true,
        focus_on_activate = true,
        key_press_enables_dpms = true,
        mouse_move_enables_dpms = true,
    },

    ecosystem = {
        no_update_news = true,
        no_donation_nag = true,
    },

    input = {
        kb_layout = "@@kb_layout@@",
        follow_mouse = 1,
        sensitivity = 0,
        touchpad = {
            natural_scroll = true,
            disable_while_typing = true,
        },
    },
})

-- ember-like motion: quick in, soft out
hl.curve("easeOutQuint",   { type = "bezier", points = { {0.23, 1},    {0.32, 1} } })
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.05}, {0.36, 1} } })
hl.curve("linear",         { type = "bezier", points = { {0, 0},       {1, 1} } })
hl.curve("almostLinear",   { type = "bezier", points = { {0.5, 0.5},   {0.75, 1} } })
hl.curve("quick",          { type = "bezier", points = { {0.15, 0},    {0.1, 1} } })
hl.curve("easy",           { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.21279333 })

hl.animation({ leaf = "global",        enabled = true, speed = 10,   bezier = "default" })
hl.animation({ leaf = "border",        enabled = true, speed = 5.39, bezier = "easeOutQuint" })
hl.animation({ leaf = "windows",       enabled = true, speed = 4.79, spring = "easy" })
hl.animation({ leaf = "windowsIn",     enabled = true, speed = 4.1,  spring = "easy",   style = "popin 87%" })
hl.animation({ leaf = "windowsOut",    enabled = true, speed = 1.49, bezier = "linear", style = "popin 87%" })
hl.animation({ leaf = "fadeIn",        enabled = true, speed = 1.73, bezier = "almostLinear" })
hl.animation({ leaf = "fadeOut",       enabled = true, speed = 1.46, bezier = "almostLinear" })
hl.animation({ leaf = "fade",          enabled = true, speed = 3.03, bezier = "quick" })
hl.animation({ leaf = "layers",        enabled = true, speed = 3.81, bezier = "easeOutQuint" })
hl.animation({ leaf = "layersIn",      enabled = true, speed = 4,    bezier = "easeOutQuint", style = "fade" })
hl.animation({ leaf = "layersOut",     enabled = true, speed = 1.5,  bezier = "linear",       style = "fade" })
hl.animation({ leaf = "workspaces",    enabled = true, speed = 1.94, bezier = "almostLinear", style = "slide" })

hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

------------------------------------------------------------------ keys
-- Same layout in every void-postinstall rice:
--   Super+Return terminal · Super+D/Space launcher · Super+Q close
--   Super+h/j/k/l (or arrows) focus · +Shift move · +Ctrl resize
--   Super+1..9 workspace · +Shift send window · Super+F fullscreen
--   Super+V float · Super+Escape lock · Super+Shift+Escape power menu
--   Print full shot · Shift+Print area shot
local function exec(cmd) return hl.dsp.exec_cmd(cmd) end

hl.bind(mod .. " + Return",         exec("rice term"))
hl.bind(mod .. " + D",              exec("rice launch"))
hl.bind(mod .. " + space",          exec("rice launch"))
hl.bind(mod .. " + Q",              hl.dsp.window.close())
hl.bind(mod .. " + F",              hl.dsp.window.fullscreen())
hl.bind(mod .. " + SHIFT + F",      hl.dsp.window.fullscreen({ mode = "maximized" }))
hl.bind(mod .. " + V",              hl.dsp.window.float({ action = "toggle" }))
hl.bind(mod .. " + P",              hl.dsp.window.pseudo())
hl.bind(mod .. " + T",              hl.dsp.layout("togglesplit"))
hl.bind(mod .. " + Tab",            hl.dsp.focus({ last = true }))
hl.bind(mod .. " + Escape",         exec("rice lock"))
hl.bind(mod .. " + SHIFT + Escape", exec("rice power"))
hl.bind(mod .. " + SHIFT + R",      exec("hyprctl reload"))
hl.bind("Print",                    exec("rice shot full"))
hl.bind("SHIFT + Print",            exec("rice shot area"))

local dirs = { h = "left", l = "right", k = "up", j = "down",
               left = "left", right = "right", up = "up", down = "down" }
local nudge = { left = { -40, 0 }, right = { 40, 0 }, up = { 0, -40 }, down = { 0, 40 } }
for key, dir in pairs(dirs) do
    hl.bind(mod .. " + " .. key,             hl.dsp.focus({ direction = dir }))
    hl.bind(mod .. " + SHIFT + " .. key,     hl.dsp.window.move({ direction = dir }))
    hl.bind(mod .. " + CTRL + " .. key,
            hl.dsp.window.resize({ x = nudge[dir][1], y = nudge[dir][2], relative = true }),
            { repeating = true })
end

for i = 1, 10 do
    local key = i % 10
    hl.bind(mod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- scratchpad
hl.bind(mod .. " + grave",         hl.dsp.workspace.toggle_special("scratch"))
hl.bind(mod .. " + SHIFT + grave", hl.dsp.window.move({ workspace = "special:scratch" }))

-- workspaces with the wheel, windows with the mouse
hl.bind(mod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mod .. " + mouse:272",  hl.dsp.window.drag(),   { mouse = true })
hl.bind(mod .. " + mouse:273",  hl.dsp.window.resize(), { mouse = true })

-- media keys (also work on the lock screen)
hl.bind("XF86AudioRaiseVolume",  exec("rice vol up"),     { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",  exec("rice vol down"),   { locked = true, repeating = true })
hl.bind("XF86AudioMute",         exec("rice vol mute"),   { locked = true })
hl.bind("XF86AudioMicMute",      exec("rice vol mic"),    { locked = true })
hl.bind("XF86MonBrightnessUp",   exec("rice light up"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", exec("rice light down"), { locked = true, repeating = true })
hl.bind("XF86AudioPlay",         exec("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPause",        exec("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioNext",         exec("playerctl next"),       { locked = true })
hl.bind("XF86AudioPrev",         exec("playerctl previous"),   { locked = true })

------------------------------------------------------------------ rules
hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})
hl.window_rule({
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})
hl.window_rule({
    name  = "float-utilities",
    match = { class = "^(pavucontrol|org.pulseaudio.pavucontrol|nm-connection-editor|blueman-manager|.blueman-manager-wrapped)$" },
    float = true,
})
hl.layer_rule({
    name  = "blur-shell",
    match = { namespace = "^(waybar|rofi|notifications)$" },
    blur = true,
    ignore_alpha = 0.3,
})
